import{a as n}from"./chunk-2JSIA3BV.js";import{a as e}from"./chunk-2RJSKV3I.js";import"./chunk-U37H3HIF.js";var t=e(n,["W\xE4hlen Sie, wo Ihre Arbeit aufbewahrt wird","Sie haben schon einen Grading-Studio-Ordner? W\xE4hlen Sie ihn, und Ihre Arbeit ist wieder da.","Nicht jetzt","Die Seitenleiste zeigt weiter „Keine Sicherung“, bis ein Ordner gew\xE4hlt ist. Klicken Sie jederzeit darauf.","Ihre Arbeit ist nicht gesichert","Mitnahmedatei erstellen","Im Moment ist Ihre Korrektur nur in diesem Browser, und das L\xF6schen der Browserdaten w\xFCrde sie entfernen. W\xE4hlen Sie einmal einen Ordner auf diesem Computer. Jedes Speichern geht dann auch dorthin, mit einer Kopie von jedem Tag zum Zur\xFCckgehen. Nichts wird hochgeladen.","Die Arbeit wurde in einem anderen Fenster ge\xE4ndert, w\xE4hrend dies offen war, daher gibt es etwas Neues zu w\xE4hlen. Noch wurde nichts \xFCbernommen.","Diese wurden sowohl hier als auch in der Datei ge\xE4ndert. W\xE4hlen Sie jeweils die gew\xFCnschte Version.","Gespeicherte Kommentare vom anderen Computer kommen zu Ihren hinzu","Ihre Arbeit wird \xFCbernommen…","\xC4nderungen an Downloads, die Sie hier haben",{one:"Eine Person wird aus der Datei \xFCbernommen",other:"{n} Lernende werden aus der Datei \xFCbernommen"},{one:"Ein Beispiel kommt hinzu oder \xE4ndert sich",other:"{n} Beispiele kommen hinzu oder \xE4ndern sich"},{one:"Eine Datei \xE4ndert sich: versp\xE4tete Dateien, Lekt\xFCren oder Word-\xC4nderungen",other:"{n} Dateien \xE4ndern sich: versp\xE4tete Dateien, Lekt\xFCren oder Word-\xC4nderungen"},"Das wurde nicht fertig. Ihre Arbeit ist sicher, und vorher wurde eine Sicherheitskopie erstellt: Wiederherstellen finden Sie unten, falls etwas falsch aussieht.","In der Datei","Diesem Browser ging der Platz aus, daher wurde das nicht fertig. Ihre Markierungen und Bewertungen hier wurden nicht ersetzt. Schaffen Sie Speicherplatz und versuchen Sie es erneut.","\xDCbernehmen","Vergessen","Am anderen Computer vergessen, daher auch hier entfernt","Bleibt vergessen",{one:"Eine \xC4nderung an Klassen, Einheiten oder Listen",other:"{n} \xC4nderungen an Klassen, Einheiten oder Listen"},"Erstellt {when}",{one:"Ein neuer Download",other:"{n} neue Downloads"},"Nichts zu \xFCbernehmen: Was hier ist, enth\xE4lt bereits alles aus dieser Datei.","Bewertungsraster oder Einstellungen, die Sie hier noch nicht haben",{one:"Eine Stunde, Datei oder Einstellung, die Ihre Planung hier nicht hat",other:"{n} Stunden, Dateien oder Einstellungen, die Ihre Planung hier nicht hat"},"Ihre Planung wird \xFCbernommen, mit Einheiten, Stundenplan und Dateien. Verkn\xFCpfen Sie ihren Ordner erneut, falls Sie einen nutzen.","Dieser Browser hat vielleicht nicht genug Platz: Er braucht etwa {need} und hat etwa {room}.","Vorher wird eine Sicherheitskopie des aktuellen Stands erstellt, Sie k\xF6nnen es unten also r\xFCckg\xE4ngig machen.",{one:"Bei einem Download gibt es nichts zu \xFCbernehmen.",other:"Bei {n} Downloads gibt es nichts zu \xFCbernehmen."},"Schulmaterialien, die am anderen Computer hinzugef\xFCgt oder ge\xE4ndert wurden",{one:"Eine Einstellung wird aus der Datei \xFCbernommen",other:"{n} Einstellungen werden aus der Datei \xFCbernommen"},"Der kleine Speicher dieses Browsers f\xFCr Listen und Einstellungen ist voll, daher wurde das nicht fertig. Ihre Markierungen und Bewertungen hier wurden nicht ersetzt.",{one:"Eine Person bleibt hier unver\xE4ndert, da diese Kopie neuer ist",other:"{n} Lernende bleiben hier unver\xE4ndert, da diese Kopie neuer ist"},{one:"eine Person",other:"{n} Lernende"},"Exportieren, was ich habe","Der Browser konnte sie nicht speichern, oft weil der Computer keinen Platz mehr hat. Lassen Sie dieses Fenster offen, schaffen Sie etwas Platz und dr\xFCcken Sie Erneut versuchen.","Ihre neuesten Markierungen und Bewertungen sind NICHT gespeichert.","Gespeichert. Ihre Arbeit ist wieder sicher.","Ihre neuesten Markierungen und Bewertungen sind nur teilweise gespeichert, in der kleinen Schnellkopie dieses Browsers.","Erneut versuchen","Arbeit \xFCbernehmen","Geben Sie die Passphrase f\xFCr {name} ein. Die ganze Datei wird gepr\xFCft, bevor sich hier etwas \xE4ndert.","Sie korrigieren an einem anderen Computer oder wechseln zu einem neuen? Erstellen Sie hier eine Mitnahmedatei und \xFCbernehmen Sie sie dort. F\xFCr den R\xFCckweg genauso.","Arbeit mitnehmen","Dies ist das Beispiel, es gibt also noch nichts von Ihnen mitzunehmen.","Eine Datei","Eine Person (anonyme Bewertung ist an)","Zur\xFCckholen","Ge\xE4ndert {when}","Bitte w\xE4hlen Sie zuerst f\xFCr jeden Eintrag eine Version.","zu einem fr\xFCheren Zeitpunkt","Keine Bewertung, Bemerkung oder Markierung",{one:"{file}: eine Markierung",other:"{file}: {n} Markierungen"},"In Ihrem Ordner","{file} geht an {key}","Dieser Download wurde vergessen, aber eine Kopie enth\xE4lt sp\xE4tere Arbeit.","Auf diesem Computer","Diese sind in diesem Browser und in Ihrem Ordner nicht gleich, deshalb wurde nichts f\xFCr Sie entschieden. Bis Sie sich entscheiden, beh\xE4lt jeder Ort seine eigene.","Sp\xE4ter entscheiden","Vergessen lassen","Korrigiert {v}","Jeweils die neueste nehmen","Keine Klasse","Nichts eingerichtet","Hier ist nichts","Aus","Meine Auswahl verwenden","An","Eine Datei geht an eine Person","Punkte: {v}","Punkte, von {n}","Diese zwei Kopien haben nicht dieselben Rasterkriterien, daher zeigt jede ihre eigenen.","Bewertungsraster: {list}",{one:"Bewertungsraster mit einem Kriterium",other:"Bewertungsraster mit {n} Kriterien"},"Die Bewertungen bleiben in jedem Fall gespeichert. Summen und Prozente richten sich nach Ihrer Wahl.","Notenblatt: {v}","Zwei Versionen zur Auswahl","Datei wird gepr\xFCft…","Datei wird gepr\xFCft… {n} von {of}","Schlie\xDFen","Entscheiden","Erledigt","Geteilte Ablagen","Letzter Ordner","Meine Ablage","F\xFCr mich freigegeben","Diese Datei ist besch\xE4digt oder wurde seit ihrer Erstellung ver\xE4ndert, daher ist sie nicht vertrauensw\xFCrdig. Hier hat sich nichts ge\xE4ndert. Erstellen Sie nach M\xF6glichkeit eine neue.","Diese Datei wurde von einer neueren Version von Grading Studio erstellt. Hier hat sich nichts ge\xE4ndert. Laden Sie diese Seite neu, um die neueste Version zu erhalten, und versuchen Sie es dann erneut.","Das ist keine Sicherung von Grading Studio.","Das ist keine Mitnahmedatei von Grading Studio.","Diese Passphrase \xF6ffnet die Datei nicht. Pr\xFCfen Sie sie und versuchen Sie es erneut. Wenn Sie sich sicher sind, ist die Datei vielleicht besch\xE4digt. Hier hat sich nichts ge\xE4ndert.","W\xE4hlen Sie einmal einen Ordner auf diesem Computer, und jedes Speichern geht dorthin und in diesen Browser, mit einer Kopie von jedem Tag zum Zur\xFCckgehen. W\xE4hlen Sie etwas Privates: Er enth\xE4lt Arbeiten von Lernenden. Wenn Chrome fragt, w\xE4hlen Sie „Bei jedem Besuch zulassen“. Wenn Sie schon einen Grading-Studio-Ordner haben, w\xE4hlen Sie ihn, und Ihre Arbeit ist wieder da.","Alles wurde aus Ihrem Ordner zur\xFCckgeholt.","Dieser Ordner lie\xDF sich nicht verwenden. Versuchen Sie einen anderen.",{one:"Aus Ihrem Ordner kam neuere Arbeit f\xFCr eine Person.",other:"Aus Ihrem Ordner kam neuere Arbeit f\xFCr {n} Lernende."},"Ordner w\xE4hlen…","Erledigt. Ihre Arbeit wird jetzt auch in „{name}“ gespeichert.","Er liegt in einem Ordner namens „{root}“ in „{name}“.","Hier wird eine Kopie Ihrer Arbeiten, Markierungen, Bewertungen, Bemerkungen, Listen und Bewertungsraster aufbewahrt, ohne Speichern-Schaltfl\xE4che, an die Sie denken m\xFCssen. Wird dieser Browser einmal gel\xF6scht, verkn\xFCpfen Sie den Ordner erneut, und alles ist wieder da.","Einige Dateien, die Ihr Ordner auflistet, fehlen oder sind besch\xE4digt und konnten nicht zur\xFCckgeholt werden. Betroffen: {list}. Ihre Markierungen, Bewertungen und Bemerkungen sind alle da. Um die Arbeiten zur\xFCckzuholen, ziehen Sie denselben Download erneut hierher.","Anderen Ordner verwenden…","Aus Ihrem Ordner kam neuere Arbeit, deshalb wurde dieser Download wieder ge\xF6ffnet.","Diesen Ordner nicht mehr verwenden","Nicht mehr verwenden","Nicht mehr in „{name}“ speichern?","Was schon im Ordner ist, bleibt dort. Darin wird nichts gel\xF6scht. Ihre Arbeit geht in diesem Browser weiter, ohne zweite Kopie.","Es wird nicht mehr in einen Ordner gespeichert. Die Dateien im Ordner sind noch da.","Um alles auf den damaligen Stand zu bringen:","Eine Aufgabe","Diese Kopie konnte nicht gelesen werden. Liegt Ihr Ordner auf einem getrennten Laufwerk, schlie\xDFen Sie es an und versuchen Sie es erneut.",{one:"die Arbeit von {n} Sch\xFCler ist anders",other:"die Arbeit von {n} Sch\xFClern ist anders"},"„{name}“ ist wieder auf dem Stand vom {when}.","Das wurde nicht fertig, daher wurde nichts wiederhergestellt.","So stand jede Aufgabe am {when}:","Ansehen","{n} bewertet","Keine der Aufgaben, die jetzt in diesem Browser sind, war in dieser Kopie.","{n} von {of} bewertet","Diese Aufgabe wiederherstellen","Diese Kopie wird gelesen…","Auf diesem Computer ist kein Platz mehr, daher wurde nichts wiederhergestellt.","Damals wie heute","die Einrichtung ist anders","Damals {then}, jetzt {now}","Das lie\xDF sich hier nicht r\xFCckg\xE4ngig machen. Die Kopie von direkt vor dem Wiederherstellen ist auf dieser Seite.","R\xFCckg\xE4ngig gemacht. „{name}“ ist wie vorher.","Der Ordner beh\xE4lt eine Kopie von jedem Tag und eine vor jeder gr\xF6\xDFeren \xC4nderung. Beim Zur\xFCckgehen werden Markierungen, Bewertungen, Bemerkungen, versp\xE4tete Dateien, Lekt\xFCren, Listen und Einstellungen auf den damaligen Stand gesetzt. Die Arbeiten bleiben.","Tageskopie","Das wurde nicht fertig. Ihre Arbeit ist vielleicht nur teilweise zur\xFCck: Nutzen Sie unten Wiederherstellen bei der neuesten Sicherheitskopie.","Zur\xFCck","Fr\xFCheren Stand ansehen","Verkn\xFCpfen Sie einen Ordner, dann beh\xE4lt er von jedem Tag eine Kopie zum Zur\xFCckgehen.","Noch keine Kopien im Ordner. Die erste wird heute erstellt.","Zu dieser Kopie vom {when} zur\xFCckgehen?","Ihre Markierungen, Bewertungen, Bemerkungen, versp\xE4teten Dateien, Lekt\xFCren, Listen und Einstellungen kehren auf den damaligen Stand zur\xFCck, in diesem Browser und im Ordner. Die Arbeiten bleiben. Vorher wird eine Kopie des aktuellen Stands erstellt, Sie k\xF6nnen es also r\xFCckg\xE4ngig machen.","\xD6ffnen","Ihre Arbeit wird gepackt…","Ihre Arbeit wird gepackt… {n} von etwa {of}","Anonyme Bewertung","Hinweise auf neue und ge\xE4nderte Dateien","Videoausschnitte","Klasse","Google Drive-Link","Gruppenarbeit","Beleuchtung","Verschobene Dateien","Eine Einstellung","Schnellkorrektur-Felder","Welche Lekt\xFCren jede Person sieht","Entfernte und ersetzte Dateien","An Lernende zur\xFCckgegeben","Ihre Antworten zu gescannten Seiten","Raster einrichten","Abdeckfelder und Freigabecodes","Richtig herum gedrehte Videos","Passphrase","Noch einmal, zur Sicherheit","W\xE4hlen Sie eine Passphrase aus ein paar W\xF6rtern. Wenn Sie sie vergessen, kann niemand diese Datei \xF6ffnen, auch Sie nicht, aber Ihre Arbeit hier ist davon nicht betroffen. Bewahren Sie die Datei trotzdem an einem privaten Ort auf.","Die beiden stimmen nicht \xFCberein.","Bitte verwenden Sie mindestens 8 Zeichen. Ein paar gew\xF6hnliche W\xF6rter funktionieren gut.","Neu verbinden","Erledigt. Wird neu geladen…","Von diesem Computer entfernen","Ihre letzte Mitnahmedatei wurde {when} erstellt, nach Ihrer letzten \xC4nderung.","Von diesem Computer entfernt. Wird neu geladen…","Nicht alles konnte entfernt werden. Schlie\xDFen Sie alle anderen Grading-Studio-Fenster und versuchen Sie es erneut.","Ihr verkn\xFCpfter Ordner „{name}“ bleibt unber\xFChrt: Seine Dateien bleiben, wo sie sind, und dieser Browser speichert nicht mehr dorthin.","Behalten","Sie haben aus diesem Browser noch keine Mitnahmedatei erstellt, was hier gemacht wurde, gibt es also vielleicht nirgendwo sonst.",{one:"Ein Download hat \xC4nderungen seit Ihrer letzten Mitnahmedatei ({when}). Diese \xC4nderungen sind nicht in dieser Datei.",other:"{n} Downloads haben \xC4nderungen seit Ihrer letzten Mitnahmedatei ({when}). Diese \xC4nderungen sind nicht in dieser Datei."},"Die Planung bleibt unber\xFChrt. Das l\xE4sst sich nicht r\xFCckg\xE4ngig machen.",{one:"Damit wird die gesamte Arbeit der Lernenden aus diesem Browser entfernt: ein Download mit Arbeiten, Markierungen, Bewertungen und Bemerkungen, dazu Listen, Einheiten, Bewertungsraster, versp\xE4tete Dateien, Lekt\xFCren, Word-\xC4nderungen, Schulmaterialien, Beispiele und Sicherheitskopien.",other:"Damit wird die gesamte Arbeit der Lernenden aus diesem Browser entfernt: {n} Downloads mit Arbeiten, Markierungen, Bewertungen und Bemerkungen, dazu Listen, Einheiten, Bewertungsraster, versp\xE4tete Dateien, Lekt\xFCren, Word-\xC4nderungen, Schulmaterialien, Beispiele und Sicherheitskopien."},"Geben Sie ENTFERNEN ein, um fortzufahren","ENTFERNEN","Vor allem Riskanten, etwa dem \xDCbernehmen von Arbeit, dem Zur\xFCckgehen oder einem neuen Jahr, wird in diesem Browser eine vollst\xE4ndige Kopie Ihrer Arbeit angelegt. Die neuesten drei bleiben erhalten. Arbeiten sind nicht enthalten, da sie sich nie \xE4ndern.","Von der aktuellen App erstellt","Sicherheitskopien","Noch keine Sicherheitskopien.","Wiederherstellen","Sicherheitskopie vom {when} wiederherstellen?","Alles kehrt auf den damaligen Stand zur\xFCck, und was seitdem hinzukam, verschwindet. Die Arbeiten bleiben, ein seitdem ge\xF6ffneter Download beh\xE4lt also seine Zeile ohne Markierungen. Der aktuelle Stand wird vorher gesichert, Sie k\xF6nnen es also r\xFCckg\xE4ngig machen.","Abbrechen","Meine Arbeit mitnehmen","Erstellt eine gesch\xFCtzte Datei mit allem, was Sie zum Korrigieren an einem anderen Computer brauchen: Dateien der Lernenden, Markierungen, Bewertungen, Bemerkungen, Listen, Bewertungsraster, Lekt\xFCren, Word-\xC4nderungen, hinzugef\xFCgte Dateien und gute Beispiele. Ihre Planung kommt auch mit: Stunden, Einheiten, Stundenplan und deren Dateien.","Erledigt: {name} ({size}). \xD6ffnen Sie Grading Studio am anderen Computer und nutzen Sie Arbeit \xFCbernehmen. F\xFCr den R\xFCckweg genauso.","Die Arbeiten fehlen in der Datei f\xFCr: {list}. Nur Markierungen und Bewertungen sind mitgekommen. Sie brauchen diese Downloads am anderen Computer.","Die Datei wurde nicht fertig und ist daher unbrauchbar. Ihre Arbeit hier ist in Ordnung. Bitte versuchen Sie es erneut an einem Ort mit mehr Platz.","Grading-Studio-Arbeit {day}","Datei erstellen","Grading-Studio-Arbeit","Keine Arbeiten f\xFCr: {list}. Dieser Browser bewahrt sie nicht auf, daher kommen nur Markierungen und Bewertungen in die Datei. Um auch die Arbeiten mitzunehmen, ziehen Sie zuerst jeden dieser Downloads hierher.","Die Datei konnte dort nicht geschrieben werden. Versuchen Sie einen anderen Ort.","Nur in diesem Browser. „{name}“ braucht einen Klick, um sich neu zu verbinden","Chrome braucht Ihr OK, um den Ordner wieder zu nutzen. W\xE4hlen Sie „Bei jedem Besuch zulassen“, dann fragt Chrome nicht mehr","Es wird gepr\xFCft, wo Ihre Arbeit liegt…",{one:"Eine Entscheidung zu Ihrem Ordner",other:"{n} Entscheidungen zu Ihrem Ordner"},"Zwei Fassungen zur Auswahl","In Ihrem Google Drive gesichert","Jede \xC4nderung geht auch in den versteckten Ordner von Grading Studio in Ihrem Google Drive","Nur in diesem Browser. Der Datentr\xE4ger mit “{name}” ist voll","{text}.","{text}. {tip}.","Nur in diesem Browser. “{name}” ist nicht erreichbar","Es holt alles von selbst nach, sobald der Ordner wieder da ist","Keine Sicherung. Nur in diesem Browser","Wenn die Daten dieses Browsers gel\xF6scht werden, ist Ihre Arbeit weg. Dieser Browser kann nicht in einen Ordner speichern, erstellen Sie also eine Mitnahmedatei, wenn Sie mit dem Korrigieren fertig sind","Wenn die Daten dieses Browsers gel\xF6scht werden, ist deine Arbeit weg. W\xE4hle einen Ordner, dann geht jede Speicherung auch dorthin","In diesem Browser und in Ihrem Ordner “{name}”","Jedes Speichern geht an beide Orte. Zuletzt um {time} im Ordner gespeichert","Jedes Speichern geht an beide Orte","Nur in diesem Browser. Der Browser hat keinen Platz mehr, daher kann “{name}” nicht aufholen","Beispiel, bleibt nur, solange Sie sich umsehen","Nichts hier ist Ihre eigene Arbeit. Verlassen Sie das Beispiel, und es wird gel\xF6scht","Speichern in Ihrem Ordner “{name}”…","Speichern in Ihrem Ordner “{name}” ({prog})…","Ihre Arbeit ist bereits in diesem Browser","Wo Ihre Arbeit gespeichert ist","das Jahr in der Datei","Ihre Klassen gehen mit leeren Klassenlisten in ein neues Jahr \xFCber. Zuerst kommt alles aus diesem Jahr in eine gesch\xFCtzte Datei, und die Datei wird gepr\xFCft, bevor hier etwas gel\xF6scht wird.","Archiviert: {list}",{one:"Eine Klasse mit ihren Einheiten und Aufgabenkarten. Jede Karte beh\xE4lt ihr Bewertungsraster und ihre Schnellkorrektur-Felder. Keine Arbeiten, Bewertungen oder Bemerkungen.",other:"{n} Klassen mit ihren Einheiten und Aufgabenkarten. Jede Karte beh\xE4lt ihr Bewertungsraster und ihre Schnellkorrektur-Felder. Keine Arbeiten, Bewertungen oder Bemerkungen."},"Was \xFCbernommen wird","Die Datei lie\xDF sich nicht genauso zur\xFCcklesen wie Ihre Arbeit hier, daher ist sie nicht vertrauensw\xFCrdig. Hier wurde nichts ge\xE4ndert. Bitte versuchen Sie es erneut an einem Ort mit mehr Platz.","Abgabetermine und Zeitraumdaten, ein Jahr sp\xE4ter","Die Datei wurde nicht fertig, daher wurde hier nichts ge\xE4ndert. Bitte versuchen Sie es erneut an einem Ort mit mehr Platz.","Das Jahr, das Sie abschlie\xDFen","Datei speichern und neues Jahr beginnen","(aus Ihren Zeitr\xE4umen)","Schuljahr","{year} in {file}, {when}","Grading-Studio-Jahr",{one:"Ein Satz Arbeiten kommt in die Datei und verl\xE4sst diesen Browser.",other:"{n} S\xE4tze Arbeiten kommen in die Datei und verlassen diesen Browser."},"Geben Sie beiden Jahren einen Namen, etwa 2025–26 und 2026–27.","Dieses Jahr: {year}","Ein archiviertes Jahr \xF6ffnen","Das wurde nicht fertig. {now} ist sicher in {file}, und vorher wurde eine Sicherheitskopie erstellt: Wiederherstellen finden Sie unten. Laden Sie neu, bevor Sie etwas anderes tun.","Beim \xD6ffnen ersetzt dieses Jahr, was jetzt hier ist. Zuerst wird {now} in einer eigenen Datei mit derselben Passphrase gespeichert und gepr\xFCft, damit Sie auf dieselbe Weise zur\xFCckwechseln k\xF6nnen.","Dieser Browser speichert nicht mehr in den Ordner „{name}“, der das aktuelle Jahr beh\xE4lt.","{now} speichern und {year} \xF6ffnen","{year} \xF6ffnen","Die Planung \xE4ndert sich nicht: Die Stunden des letzten Jahres sind bereits unter Fr\xFChere Stunden.",{one:"Die Datei enth\xE4lt einen Satz Arbeiten mit Klassen, Klassenlisten, Markierungen und Bewertungen, erstellt {when}.",other:"Die Datei enth\xE4lt {n} S\xE4tze Arbeiten mit Klassen, Klassenlisten, Markierungen und Bewertungen, erstellt {when}."},"W\xE4hlen Sie eine Passphrase aus ein paar W\xF6rtern. Ohne sie kann niemand die Datei \xF6ffnen, auch Sie nicht, also notieren Sie sie an einem sicheren Ort.","Planungseinheiten und das Halbjahr, ein Jahr sp\xE4ter. Die Stunden dieses Jahres wandern zu Fr\xFChere Stunden und sind bereit zur Wiederverwendung.","Datei sch\xFCtzen","Klassenlisten, nur f\xFCr Klassen mit denselben Lernenden. Sonst bleiben sie leer und die Beobachtungsliste wird geleert.","Das neue Jahr braucht einen anderen Namen als das, das Sie abschlie\xDFen.","{year} wird in eine Datei gespeichert…","Ein neues Schuljahr beginnen","Das neue Jahr wurde nicht fertig eingerichtet. Alles aus {year} ist sicher in {file}, und vorher wurde eine Sicherheitskopie erstellt: Wiederherstellen finden Sie unten, falls etwas falsch aussieht.","{year} hat begonnen","Ihre Klassen, Einheiten und Aufgabenkarten sind bereit. F\xFCgen Sie die Lernenden jeder Klasse im Reiter Lernende ein, falls die Listen leer sind. Alles aus {from} ist in {file} ({size}), gepr\xFCft. Bewahren Sie die Datei mit ihrer Passphrase sicher auf. Mit Ein archiviertes Jahr \xF6ffnen holen Sie sie zur\xFCck.","{year} wird gestartet…","Ihre Einstellungen, Notenskala, gespeicherten Bewertungsraster und Kommentarsammlung bleiben, wie sie sind.","Das neue Jahr"],null);export{t as default};
